{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C75","C74","C77","C78","C79","C80","C84","C85","C52","C51","C59","C54","C71","C69","C70","C66","C72"],
  "contradictory_card_ids": ["C76"],
  "prediction_basis_card_ids": ["C75","C84","C77","C78","C52","C59","C71","C69"],
  "claims": [
    {
      "claim": "L6 shows that the closest analog (JNJ-56914845, M01) is primarily metabolized by CYP3A4 (C75), and atazanavir, a comparably sized peptidomimetic carbamate, has high intrinsic clearance in human liver microsomes (139.8 µL/min/mg, C84) and rat hepatocytes (129–165 µL/min/10^6 cells, C77/C78), providing mechanistic evidence for hepatic first-pass loss in this chemotype.",
      "card_ids": ["C75","C84","C77","C78"]
    },
    {
      "claim": "L4 measured very low aqueous solubility/dissolution for related large carbamate–imidazole HCV inhibitors and atazanavir (parent PIB <0.1 mg/mL at pH 7.4, C52; atazanavir <1 µg/mL at pH≥4 and 30.56% pure-drug dissolution, C59/C54), supporting poor dissolution/absorption for the query.",
      "card_ids": ["C52","C59","C54"]
    },
    {
      "claim": "L5 identifies multiple HCV NS5A inhibitors of the same structural class (pibrentasvir, ledipasvir, ombitasvir, velpatasvir) as P-gp/BCRP substrates whose intestinal efflux can reduce oral exposure (C71, C69, C70, C66, C72), supporting presystemic loss.",
      "card_ids": ["C71","C69","C70","C66","C72"]
    },
    {
      "claim": "C76 reports low hepatic extraction (<12.7%) for a ledipasvir-like NS5A inhibitor in cynomolgus monkey microsomes, but this is less transferable (different core, cyno assay, single record) and does not overturn the coherent solubility, efflux, and hepatic-metabolism evidence.",
      "card_ids": ["C76"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C75","C74","C77","C78","C79","C80","C84","C85","C76"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental absolute oral bioavailability measurement for the query molecule.",
    "No query-specific human hepatic clearance or metabolic stability assay; L6 values are for close analogs (JNJ-56914845) and atazanavir, not the query itself.",
    "No query-specific permeability (e.g., Caco-2/PAMPA) or intestinal absorption data; L4 contains solubility/dissolution records only.",
    "No query-specific efflux assay; L5 substrate status is for related HCV NS5A inhibitors, not the query directly.",
    "No dose, formulation, or food-effect information for the query, which could alter the impact of low intrinsic solubility and efflux."
  ],
  "decision_summary": "L6 adds hepatic clearance and metabolic stability evidence: the closest analog is CYP3A4-metabolized (C75) and atazanavir shows high intrinsic clearance in human liver microsomes and rat hepatocytes (C84, C77/C78), coherently supporting hepatic first-pass loss. One contradictory record (C76, low hepatic extraction for a ledipasvir-like NS5A inhibitor in cyno microsomes) is less transferable and does not overturn the combined solubility, efflux, and metabolism evidence. Prediction kept low with moderate confidence."
}

